using System.Collections.Concurrent;
using JasperFx.Events;                 // IEvent, IEvent<T>
using Marten;                           // IQuerySession
using JasperFx.Events.Grouping;         // IEventGrouping — NOT Marten.Events.Aggregation, and no doc page says so
using Marten.Events.Aggregation;        // IAggregateGrouper, SingleStreamProjection
using Marten.Events.Projections;        // MultiStreamProjection
using Campaigns.Contracts;

namespace Campaigns.Views;

/// <summary>
/// Context: campaigns. Slice: campaign-dashboard.
/// Fed by CampaignOpened, CampaignClosed, MessageQueued, MessageDelivered, MessageBounced.
///
/// RECIPE 4: a MultiStreamProjection spanning TWO STREAM TYPES.
///
/// One row per campaign, built from Campaign events and Message events together. Three of the five carry
/// campaignId, so those are plain <c>Identity&lt;T&gt;</c> rules. The other two — MessageDelivered and
/// MessageBounced — do not, and that is where the interesting cost is. See MessageToCampaignGrouper.
///
/// REGISTERED ASYNC, which is Marten's own default for multi-stream and not a formality. The docs' reason:
/// under load, concurrent writes to different streams that both land on one row can stomp each other and
/// produce "apparent event skipping". SenderMonthly next door is registered Inline on purpose, so the two
/// costs are visible side by side in one project:
///
///   Async   needs AddAsyncDaemon, and every test that reads this view must WAIT rather than assert
///   Inline  assertable the moment the write returns, and exposed to that contention
/// </summary>
public sealed record CampaignDashboard
{
    public Guid Id { get; init; }

    public Guid CampaignId { get; init; }

    public string Name { get; init; } = default!;

    /// <summary>Computed from CampaignOpened + CampaignClosed — a fold over event PRESENCE.</summary>
    public string Status { get; init; } = default!;

    /// <summary>Computed from MessageQueued: how many messages, not a field on anything.</summary>
    public int Queued { get; init; }

    public int Delivered { get; init; }

    public int Bounced { get; init; }

    public const string Open = "Open";
    public const string Closed = "Closed";
}

/// <summary>
/// Note the Apply methods RETURN the view rather than mutating it. The record is init-only, so a void
/// <c>Apply(TEvent, TView)</c> would have nothing it could write to — Marten supports both shapes and the
/// choice follows from the view being a record, which is what the generator emits.
/// </summary>
public sealed partial class CampaignDashboardProjection : MultiStreamProjection<CampaignDashboard, Guid>
{
    public CampaignDashboardProjection()
    {
        // The three events that carry the view's key. Nothing clever needed.
        Identity<CampaignOpened>(e => e.CampaignId);
        Identity<CampaignClosed>(e => e.CampaignId);
        Identity<MessageQueued>(e => e.CampaignId);

        // The two that do not. Additive to the Identity rules above — a custom IEventSlicer would have
        // REPLACED them, which is the distinction between the two extension points.
        CustomGrouping(new MessageToCampaignGrouper());
    }

    public CampaignDashboard Apply(CampaignOpened e, CampaignDashboard view) => view with
    {
        Id = e.CampaignId,
        CampaignId = e.CampaignId,
        Name = e.Name,
        Status = CampaignDashboard.Open,
    };

    public CampaignDashboard Apply(CampaignClosed e, CampaignDashboard view) => view with
    {
        Id = e.CampaignId,
        CampaignId = e.CampaignId,
        Status = CampaignDashboard.Closed,
    };

    public CampaignDashboard Apply(MessageQueued e, CampaignDashboard view) => view with
    {
        Id = e.CampaignId,
        CampaignId = e.CampaignId,
        Queued = view.Queued + 1,
    };

    // These two cannot set Id or CampaignId: the event does not carry it. Marten assigns the document
    // identity from the slice the grouper put the event in, which is the whole point of the grouper.
    public CampaignDashboard Apply(MessageDelivered e, CampaignDashboard view) => view with
    {
        Delivered = view.Delivered + 1,
    };

    public CampaignDashboard Apply(MessageBounced e, CampaignDashboard view) => view with
    {
        Bounced = view.Bounced + 1,
    };
}

/// <summary>
/// The lookup this grouper reads. It is NOT on the event model, deliberately — nobody reads it, no screen
/// displays it, and it answers no business question. It is a mechanism: the index that lets an outcome
/// event find its campaign. Putting it on the model would be modelling the implementation.
///
/// Registered INLINE while CampaignDashboard is Async, and that ordering is the point: the link row is
/// committed in the append's own transaction, so by the time the daemon groups a later batch the mapping
/// is already there to be found.
/// </summary>
public sealed record MessageCampaignLink
{
    public Guid Id { get; init; }

    public Guid CampaignId { get; init; }
}

public sealed partial class MessageCampaignLinkProjection : SingleStreamProjection<MessageCampaignLink, Guid>
{
    public static MessageCampaignLink Apply(MessageQueued e, MessageCampaignLink current) => current with
    {
        Id = e.MessageId,
        CampaignId = e.CampaignId,
    };
}

/// <summary>
/// BATCH-AWARE, because the alternative is silent data loss — under one condition, and the condition was
/// measured rather than assumed.
///
/// Marten's docs describe the trap under "Grouping events when the aggregate id is not on the event": if a
/// MessageQueued and a MessageDelivered for the same message land in the SAME batch, a grouper that only
/// queries the lookup finds no row yet, drops the outcome event, and RAISES NOTHING. The counter is one
/// short, forever.
///
/// Removing step 1 and re-running the test showed the race does NOT occur here — because
/// MessageCampaignLinkProjection is registered Inline, so its row is committed in the append's own
/// transaction and is already there when the daemon groups the page. Switch that registration to Async and
/// the same test fails exactly as described: <c>row.Delivered should be 1 but was 0</c>.
///
/// | lookup lifecycle | step 1 | same-batch outcome        |
/// |------------------|--------|---------------------------|
/// | Inline           | on/off | counted                   |
/// | Async            | on     | counted                   |
/// | Async            | off    | **silently lost**         |
///
/// Step 1 is kept, because it makes the grouper correct independently of a registration line in another
/// file. That is worth a few lines: the failure mode is a number that is quietly wrong.
///
/// The same docs page warns separately that a grouper must never query the projection it is building.
/// That is why the link lives in its own document rather than as a field on CampaignDashboard: grouping
/// runs in parallel with view construction, so the view is not readable from here at all.
///
/// The instance cache is safe because Marten keeps one grouper for the lifetime of the registration. It is
/// also unbounded — fine for a reference model, an LRU in anything long-running.
/// </summary>
public sealed class MessageToCampaignGrouper : IAggregateGrouper<Guid>
{
    private readonly ConcurrentDictionary<Guid, Guid> _campaignOf = new();

    public async Task Group(IQuerySession session, IEnumerable<IEvent> events, IEventGrouping<Guid> grouping)
    {
        var outcomes = events.Where(e => e.Data is MessageDelivered or MessageBounced).ToList();
        if (outcomes.Count == 0) return;

        // 1) Links that share THIS batch. Without this the same-batch case silently loses events.
        foreach (var queued in events.OfType<IEvent<MessageQueued>>())
            _campaignOf[queued.Data.MessageId] = queued.Data.CampaignId;

        // 2) Anything still unknown was linked by an earlier batch, so it is in the inline lookup.
        var unresolved = outcomes
            .Select(MessageIdOf)
            .Distinct()
            .Where(id => !_campaignOf.ContainsKey(id))
            .ToList();

        if (unresolved.Count > 0)
        {
            var links = await session.Query<MessageCampaignLink>()
                .Where(x => unresolved.Contains(x.Id))
                .ToListAsync();

            foreach (var link in links) _campaignOf[link.Id] = link.CampaignId;
        }

        // 3) Route each outcome to its campaign's row. An event whose message is still unknown is
        //    deliberately left ungrouped rather than guessed at.
        foreach (var e in outcomes)
            if (_campaignOf.TryGetValue(MessageIdOf(e), out var campaignId))
                grouping.AddEvent(campaignId, e);
    }

    private static Guid MessageIdOf(IEvent e) => e.Data switch
    {
        MessageDelivered d => d.MessageId,
        MessageBounced b => b.MessageId,
        _ => Guid.Empty,
    };
}
